function [sum, prod, at_k, count, last] = loops(v, k)
%LOOPS  Loops, a record, and an index that is computed.
%   v: real[m][6] (passed in m)
%   k: int (passed a whole number)
%   returns sum: real[m] (passed in m)
%   returns prod: real[1] (passed a plain number)
%   returns at_k: real[m] (passed in m)
%   returns count: int (passed a whole number)
%   returns last: real[m][3] (passed in m)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    sum = 0;
    prod = 0;
    at_k = 0;
    count = 0;
    last = zeros(3, 1);
    p = asils.pcselftest.selftest.Probe_zero();
    sum = 0;
    prod = 1;
    count = 0;
    for i = (0):((6) - 1)
        sum = (sum + v((i) + 1));
        prod = (prod * (1 + (v((i) + 1) / 10)));
        if (v((i) + 1) > 0)
            count = (count + 1);
            p.k = i;
            p.seen = true;
        end
    end
    for j = (0):((3) - 1)
        p.v((j) + 1) = v(((j + 3)) + 1);
        p.m((j) + 1, (j) + 1) = 1;
    end
    at_k = v((k) + 1);
    last = [p.m(1, 1)*p.v(1) + p.m(1, 2)*p.v(2) + p.m(1, 3)*p.v(3); p.m(2, 1)*p.v(1) + p.m(2, 2)*p.v(2) + p.m(2, 3)*p.v(3); p.m(3, 1)*p.v(1) + p.m(3, 2)*p.v(2) + p.m(3, 3)*p.v(3)];
    if (~p.seen)
        last = [0; 0; 0];
    end
end
